import datetime
import re

from ta_moler.events.unix_syslog.genericunix_syslog_lineevent import GenericUnixSyslogLineEvent


class Ue5gRach(GenericUnixSyslogLineEvent):
    """Ue5GRach event class."""

    # /L2-PS/src/dl/sch/pre/rach/PrachReceiver.cpp[163] Preamble prachRecvXsfn=369.29 subcellIndex=0 preambleIdx=15 peakMetric=1700.661865 timeOccasion=2 freqOccasion=0 initialTa=0
    _re_prach_reciver_pattern = re.compile(
        r"/L2-PS/src/dl/sch/pre/rach/PrachReceiver.*subcellIndex=(?P<SUBCELL>\d+).*preambleIdx=(?P<PREAMBLE>\d+).*"
    )

    # /L2-PS/src/dl/sch/pre/rach/RaProcedure.cpp[180] RaProcedure::handlePrachPreamble: xsfn[369:36] prachXsfn[369:29] cRnti=98 raRnti=415 prachPreambleIndex=15 initialTa=0 TimeOccasion=2 FreqOccasion=0 BeamId=8
    _re_ra_procedure_pattern = re.compile(
        r"/L2-PS/src/dl/sch/pre/rach/RaProcedure.*handlePrachPreamble.*prachPreambleIndex=(?P<PREAMBLE>\d+).*[Bb]eamId=(?P<BEAM>\d+).*"
    )

    # /L2-PS/src/ul/sch/pre/rach/RaProcedure.cpp[1200] handleAckNackForContRes: UE attached: xsfn=370.0 rnti=61
    _re_ue_attached_pattern = re.compile(r"/L2-PS/src/ul/sch/pre/rach/RaProcedure.*UE attached:.*")

    def __init__(self, connection, till_occurs_times=-1, runner=None):
        """
        Event for 'Wait for cell status to change from Offline to Online'.

        :param connection: moler connection to device, terminal when command is executed
        :param till_occurs_times: number of event occurrence
        :param runner: Runner to run event
        """
        super(Ue5gRach, self).__init__(
            connection=connection,
            runner=runner,
            till_occurs_times=till_occurs_times,
            detect_patterns=[Ue5gRach._re_prach_reciver_pattern, Ue5gRach._re_ra_procedure_pattern, Ue5gRach._re_ue_attached_pattern],
            match="sequence",
        )


